    '¿Tienes cuenta? <a href="cuenta.php">Entra</a> y no tendrás que escribir tus datos.' => ['en' => 'Have an account? <a href="cuenta.php">Sign in</a> and you won’t need to type your details.', 'pt' => 'Tem conta? <a href="cuenta.php">Entre</a> e não terá de escrever os seus dados.', 'gl' => 'Tes conta? <a href="cuenta.php">Entra</a> e non terás que escribir os teus datos.'],
    'Teléfono móvil' => ['en' => 'Mobile phone', 'pt' => 'Telemóvel', 'gl' => 'Teléfono móbil'],
    'obligatorio: te enviaremos un WhatsApp para confirmar' => ['en' => 'required: we’ll send you a WhatsApp message to confirm', 'pt' => 'obrigatório: vamos enviar-lhe um WhatsApp para confirmar', 'gl' => 'obrigatorio: enviarémosche un WhatsApp para confirmar'],
    'opcional' => ['en' => 'optional', 'pt' => 'opcional', 'gl' => 'opcional'],
    'Ponlo si quieres recibir la confirmación por email.' => ['en' => 'Add it if you’d like to receive the confirmation by email.', 'pt' => 'Indique-o se quiser receber a confirmação por email.', 'gl' => 'Ponlo se queres recibir a confirmación por correo.'],
    'Ponlo si quieres recibir la confirmación por email o ver esta reserva en una cuenta: solo aparecerá en la cuenta que crees con este mismo email. Sin email, la reserva no se puede añadir a una cuenta.' => ['en' => 'Add it if you’d like to receive the confirmation by email or see this booking in an account: it will only appear in an account you create with this same email. Without an email, the booking can’t be added to an account.', 'pt' => 'Indique-o se quiser receber a confirmação por email ou ver esta reserva numa conta: só aparecerá na conta que criar com este mesmo email. Sem email, a reserva não pode ser adicionada a uma conta.', 'gl' => 'Ponlo se queres recibir a confirmación por correo ou ver esta reserva nunha conta: só aparecerá na conta que crees con este mesmo correo. Sen correo, a reserva non se pode engadir a unha conta.'],
    'Algo que debamos saber' => ['en' => 'Anything we should know', 'pt' => 'Algo que devamos saber', 'gl' => 'Algo que debamos saber'],
    '<strong>Protección de datos.</strong> Responsable: %s. Finalidad: gestionar tu reserva; el teléfono solo se usa para enviarte el WhatsApp de confirmación. Tus datos se borran 24 horas después de la reserva y no se ceden a nadie. Puedes acceder a ellos, corregirlos o borrarlos escribiendo a %s.' => ['en' => '<strong>Data protection.</strong> Controller: %s. Purpose: managing your booking; your phone number is only used to send you the WhatsApp confirmation. Your data is deleted 24 hours after the booking and is not shared with anyone. You can access, correct or delete it by writing to %s.', 'pt' => '<strong>Proteção de dados.</strong> Responsável: %s. Finalidade: gerir a sua reserva; o telefone só é usado para lhe enviar o WhatsApp de confirmação. Os seus dados são apagados 24 horas depois da reserva e não são cedidos a ninguém. Pode aceder-lhes, retificá-los ou apagá-los escrevendo para %s.', 'gl' => '<strong>Protección de datos.</strong> Responsable: %s. Finalidade: xestionar a túa reserva; o teléfono só se usa para enviarche o WhatsApp de confirmación. Os teus datos bórranse 24 horas despois da reserva e non se ceden a ninguén. Podes acceder a eles, corrixilos ou borralos escribindo a %s.'],
    'Enviar petición' => ['en' => 'Send request', 'pt' => 'Enviar pedido', 'gl' => 'Enviar petición'],
    'Hecho' => ['en' => 'Done', 'pt' => 'Concluído', 'gl' => 'Feito'],
    'Esa fecha ya ha pasado' => ['en' => 'That date has already passed', 'pt' => 'Essa data já passou', 'gl' => 'Esa data xa pasou'],
    'Solo se puede reservar con %d días de antelación como máximo' => ['en' => 'You can only book up to %d days in advance', 'pt' => 'Só é possível reservar com um máximo de %d dias de antecedência', 'gl' => 'Só se pode reservar con %d días de antelación como máximo'],
    'Ya no se puede reservar para hoy' => ['en' => 'It’s no longer possible to book for today', 'pt' => 'Já não é possível reservar para hoje', 'gl' => 'Xa non se pode reservar para hoxe'],
    'Esa hora no está disponible' => ['en' => 'That time isn’t available', 'pt' => 'Essa hora não está disponível', 'gl' => 'Esa hora non está dispoñible'],
    'Esa hora ya está completa, prueba otra' => ['en' => 'That time is fully booked, try another', 'pt' => 'Essa hora já está completa, experimente outra', 'gl' => 'Esa hora xa está completa, proba outra'],
    'Hemos recibido tu petición para el %s a las %s (%s).' => ['en' => 'We’ve received your request for %s at %s (%s).', 'pt' => 'Recebemos o seu pedido para %s às %s (%s).', 'gl' => 'Recibimos a túa petición para o %s ás %s (%s).'],
    'Hola %s, confirma tu reserva en %s para el %s a las %s (%s). Abre este enlace y pulsa «Confirmar mi reserva»:' => ['en' => 'Hi %s, please confirm your booking at %s for %s at %s (%s). Open this link and tap “Confirm my booking”:', 'pt' => 'Olá, %s, confirme a sua reserva em %s para %s às %s (%s). Abra esta ligação e toque em «Confirmar a minha reserva»:', 'gl' => 'Ola, %s, confirma a túa reserva en %s para o %s ás %s (%s). Abre esta ligazón e preme «Confirmar a miña reserva»:'],
    'Si te has equivocado en algún dato, vuelve a hacer la reserva en la web:' => ['en' => 'If any detail is wrong, make the booking again on the website:', 'pt' => 'Se se enganou em algum dado, volte a fazer a reserva no site:', 'gl' => 'Se te equivocaches nalgún dato, volve facer a reserva na web:'],
    '%s a las %s' => ['en' => '%s at %s', 'pt' => '%s às %s', 'gl' => '%s ás %s'],
    'Si necesitas cambiar algo, llámanos al %s.' => ['en' => 'If you need to change anything, call us on %s.', 'pt' => 'Se precisar de alterar alguma coisa, ligue-nos para o %s.', 'gl' => 'Se precisas cambiar algo, chámanos ao %s.'],
    'Confirma tu reserva en %s' => ['en' => 'Confirm your booking at %s', 'pt' => 'Confirme a sua reserva em %s', 'gl' => 'Confirma a túa reserva en %s'],
    'También te lo hemos enviado por WhatsApp. Si te has equivocado en algún dato, vuelve a hacer la reserva en la web.' => ['en' => 'We’ve also sent it to you by WhatsApp. If any detail is wrong, make the booking again on the website.', 'pt' => 'Também lho enviámos por WhatsApp. Se se enganou em algum dado, volte a fazer a reserva no site.', 'gl' => 'Tamén cho enviamos por WhatsApp. Se te equivocaches nalgún dato, volve facer a reserva na web.'],
    'Reserva confirmada en %s' => ['en' => 'Booking confirmed at %s', 'pt' => 'Reserva confirmada em %s', 'gl' => 'Reserva confirmada en %s'],
    'No podemos atender tu reserva en %s' => ['en' => 'We can’t take your booking at %s', 'pt' => 'Não podemos aceitar a sua reserva em %s', 'gl' => 'Non podemos atender a túa reserva en %s'],
    'Reserva cancelada en %s' => ['en' => 'Booking cancelled at %s', 'pt' => 'Reserva cancelada em %s', 'gl' => 'Reserva cancelada en %s'],
    'Hola %s, te recordamos tu reserva en %s el %s a las %s (%s). ¡Te esperamos!' => ['en' => 'Hi %s, this is a reminder of your booking at %s on %s at %s (%s). See you soon!', 'pt' => 'Olá, %s, lembramos a sua reserva em %s para %s às %s (%s). Esperamos por si!', 'gl' => 'Ola %s, lembrámosche a túa reserva en %s o %s ás %s (%s). Agardámoste!'],
    'Tu reserva del %s ha quedado cancelada.' => ['en' => 'Your booking for %s has been cancelled.', 'pt' => 'A sua reserva de %s foi cancelada.', 'gl' => 'A túa reserva do %s quedou cancelada.'],
    'Reservas como %s. Tus reservas están en <a href="cuenta.php">tu cuenta</a>.' => ['en' => 'You’re booking as %s. Your bookings are in <a href="cuenta.php">your account</a>.', 'pt' => 'Está a reservar como %s. As suas reservas estão na <a href="cuenta.php">sua conta</a>.', 'gl' => 'Reservas como %s. As túas reservas están na <a href="cuenta.php">túa conta</a>.'],
    'Con una <a href="cuenta.php?registro=1">cuenta</a> reservas más rápido y puedes ver o cancelar tus reservas.' => ['en' => 'With an <a href="cuenta.php?registro=1">account</a> you book faster and can see or cancel your bookings.', 'pt' => 'Com uma <a href="cuenta.php?registro=1">conta</a> reserva mais depressa e pode ver ou cancelar as suas reservas.', 'gl' => 'Cunha <a href="cuenta.php?registro=1">conta</a> reservas máis rápido e podes ver ou cancelar as túas reservas.'],
    'Hoy' => ['en' => 'Today', 'pt' => 'Hoje', 'gl' => 'Hoxe'],
    'Cancelación' => ['en' => 'Cancellation', 'pt' => 'Cancelamento', 'gl' => 'Cancelación'],
    'Siempre gratis' => ['en' => 'Always free', 'pt' => 'Sempre gratuito', 'gl' => 'Sempre gratis'],
    'Retrasos' => ['en' => 'Running late', 'pt' => 'Atrasos', 'gl' => 'Atrasos'],
    'Políticas' => ['en' => 'Policies', 'pt' => 'Políticas', 'gl' => 'Políticas'],
    'Reservas y cancelaciones' => ['en' => 'Bookings and cancellations', 'pt' => 'Reservas e cancelamentos', 'gl' => 'Reservas e cancelacións'],
    'También puedes llamarnos al %s.' => ['en' => 'You can also call us on %s.', 'pt' => 'Também pode ligar-nos para o %s.', 'gl' => 'Tamén podes chamarnos ao %s.'],
    'Si llegas tarde' => ['en' => 'If you’re running late', 'pt' => 'Se se atrasar', 'gl' => 'Se chegas tarde'],
    'Tus datos' => ['en' => 'Your data', 'pt' => 'Os seus dados', 'gl' => 'Os teus datos'],
    'Usamos tus datos solo para gestionar tus reservas y se guardan cifrados. El nombre, el teléfono y el email de cada reserva se borran solos 24 horas después. No los cedemos a nadie ni te enviamos publicidad. Lee la <a href="legal.php#privacidad">política de privacidad</a>.' => ['en' => 'We only use your data to manage your bookings and it is stored encrypted. The name, phone number and email of each booking are deleted automatically 24 hours later. We don’t share them with anyone or send you advertising. Read the <a href="legal.php#privacidad">privacy policy</a>.', 'pt' => 'Usamos os seus dados apenas para gerir as suas reservas e são guardados cifrados. O nome, o telefone e o email de cada reserva são apagados automaticamente 24 horas depois. Não os cedemos a ninguém nem lhe enviamos publicidade. Leia a <a href="legal.php#privacidad">política de privacidade</a>.', 'gl' => 'Usamos os teus datos só para xestionar as túas reservas e gárdanse cifrados. O nome, o teléfono e o correo de cada reserva bórranse sos 24 horas despois. Non os cedemos a ninguén nin che enviamos publicidade. Le a <a href="legal.php#privacidad">política de privacidade</a>.'],
    'El servidor no responde bien. Inténtalo de nuevo.' => ['en' => 'The server isn’t responding properly. Please try again.', 'pt' => 'O servidor não está a responder bem. Tente novamente.', 'gl' => 'O servidor non responde ben. Téntao de novo.'],
    'Sin conexión. Revisa internet e inténtalo de nuevo.' => ['en' => 'No connection. Check your internet and try again.', 'pt' => 'Sem ligação. Verifique a internet e tente novamente.', 'gl' => 'Sen conexión. Revisa internet e téntao de novo.'],
    'Algo ha fallado' => ['en' => 'Something went wrong', 'pt' => 'Algo correu mal', 'gl' => 'Algo fallou'],
