    'Esperando confirmación. Mientras no abras el enlace del WhatsApp y pulses «Confirmar mi reserva», la reserva queda pendiente.' => ['en' => 'Waiting for confirmation. Until you open the WhatsApp link and tap “Confirm my booking”, the booking stays pending.', 'pt' => 'À espera de confirmação. Enquanto não abrir a ligação do WhatsApp e tocar em «Confirmar a minha reserva», a reserva fica pendente.', 'gl' => 'Agardando confirmación. Mentres non abras a ligazón do WhatsApp e premas «Confirmar a miña reserva», a reserva queda pendente.'],
    'Esperando confirmación. La verás en <a href="cuenta.php">tu cuenta</a>, donde también podrás cancelarla.' => ['en' => 'Waiting for confirmation. You’ll see it in <a href="cuenta.php">your account</a>, where you can also cancel it.', 'pt' => 'À espera de confirmação. Vai vê-la na <a href="cuenta.php">sua conta</a>, onde também a pode cancelar.', 'gl' => 'Agardando confirmación. Verala na <a href="cuenta.php">túa conta</a>, onde tamén poderás cancelala.'],
    'Si creas una cuenta con el mismo email, también la verás allí.' => ['en' => 'If you create an account with the same email, you’ll see it there too.', 'pt' => 'Se criar uma conta com o mesmo email, também a verá lá.', 'gl' => 'Se creas unha conta co mesmo correo, tamén a verás alí.'],
    'Como no has puesto email, esta reserva no aparecerá en ninguna cuenta.' => ['en' => 'As you didn’t give an email, this booking won’t appear in any account.', 'pt' => 'Como não indicou email, esta reserva não aparecerá em nenhuma conta.', 'gl' => 'Como non puxeches correo, esta reserva non aparecerá en ningunha conta.'],
    'Un momento…' => ['en' => 'One moment…', 'pt' => 'Um momento…', 'gl' => 'Un momento…'],
    'Datos guardados' => ['en' => 'Details saved', 'pt' => 'Dados guardados', 'gl' => 'Datos gardados'],
    'Email enviado otra vez' => ['en' => 'Email sent again', 'pt' => 'Email enviado novamente', 'gl' => 'Correo enviado outra vez'],
    '¿Cancelar la reserva del %s?' => ['en' => 'Cancel the booking for %s?', 'pt' => 'Cancelar a reserva de %s?', 'gl' => 'Cancelar a reserva do %s?'],
    '%s · página %s de %s' => ['en' => '%s · page %s of %s', 'pt' => '%s · página %s de %s', 'gl' => '%s · páxina %s de %s'],
    'Puedes cambiar tu elección cuando quieras.' => ['en' => 'You can change your choice at any time.', 'pt' => 'Pode mudar a sua escolha quando quiser.', 'gl' => 'Podes cambiar a túa elección cando queiras.'],
    'Necesarias' => ['en' => 'Necessary', 'pt' => 'Necessários', 'gl' => 'Necesarias'],
    'Mantienen tu sesión y recuerdan esta elección. Siempre activas.' => ['en' => 'They keep you signed in and remember this choice. Always on.', 'pt' => 'Mantêm a sua sessão e lembram esta escolha. Sempre ativos.', 'gl' => 'Manteñen a túa sesión e lembran esta elección. Sempre activas.'],
    'Análisis' => ['en' => 'Analytics', 'pt' => 'Análise', 'gl' => 'Análise'],
    'Estadísticas de visitas (Google Analytics).' => ['en' => 'Visit statistics (Google Analytics).', 'pt' => 'Estatísticas de visitas (Google Analytics).', 'gl' => 'Estatísticas de visitas (Google Analytics).'],
    'Publicidad' => ['en' => 'Advertising', 'pt' => 'Publicidade', 'gl' => 'Publicidade'],
    'Desactivada: tu navegador pide no compartir datos (GPC).' => ['en' => 'Off: your browser asks not to share data (GPC).', 'pt' => 'Desativada: o seu navegador pede para não partilhar dados (GPC).', 'gl' => 'Desactivada: o teu navegador pide non compartir datos (GPC).'],
    'Medir anuncios en Google, Instagram o Facebook. Implica compartir datos con esas empresas.' => ['en' => 'Measure ads on Google, Instagram or Facebook. This means sharing data with those companies.', 'pt' => 'Medir anúncios na Google, Instagram ou Facebook. Implica partilhar dados com essas empresas.', 'gl' => 'Medir anuncios en Google, Instagram ou Facebook. Implica compartir datos con esas empresas.'],
    'Rechazar todas' => ['en' => 'Reject all', 'pt' => 'Rejeitar todos', 'gl' => 'Rexeitar todas'],
    'Configurar' => ['en' => 'Settings', 'pt' => 'Configurar', 'gl' => 'Configurar'],
    'Guardar elección' => ['en' => 'Save choice', 'pt' => 'Guardar escolha', 'gl' => 'Gardar elección'],
    'Aceptar todas' => ['en' => 'Accept all', 'pt' => 'Aceitar todos', 'gl' => 'Aceptar todas'],
    'Usamos cookies necesarias para que la web funcione y, si nos das permiso, cookies de análisis para saber cómo se usa la web y mejorarla, y de publicidad para medir nuestros anuncios.' => ['en' => 'We use necessary cookies to make the website work and, with your permission, analytics cookies to understand how the website is used and improve it, and advertising cookies to measure our ads.', 'pt' => 'Usamos cookies necessários para o site funcionar e, com a sua autorização, cookies de análise para saber como o site é usado e melhorá-lo, e de publicidade para medir os nossos anúncios.', 'gl' => 'Usamos cookies necesarias para que a web funcione e, se nos das permiso, cookies de análise para saber como se usa a web e mellorala, e de publicidade para medir os nosos anuncios.'],
    'Usamos cookies necesarias para que la web funcione y, si nos das permiso, cookies de análisis para saber cómo se usa la web y mejorarla.' => ['en' => 'We use necessary cookies to make the website work and, with your permission, analytics cookies to understand how the website is used and improve it.', 'pt' => 'Usamos cookies necessários para o site funcionar e, com a sua autorização, cookies de análise para saber como o site é usado e melhorá-lo.', 'gl' => 'Usamos cookies necesarias para que a web funcione e, se nos das permiso, cookies de análise para saber como se usa a web e mellorala.'],
    'Fecha no válida' => ['en' => 'Invalid date', 'pt' => 'Data inválida', 'gl' => 'Data non válida'],
    'Escribe un nombre' => ['en' => 'Enter a name', 'pt' => 'Escreva um nome', 'gl' => 'Escribe un nome'],
