    'Has hecho demasiadas reservas seguidas. Llámanos por teléfono.' => ['en' => 'You’ve made too many bookings in a row. Please call us.', 'pt' => 'Fez demasiadas reservas seguidas. Ligue-nos.', 'gl' => 'Fixeches demasiadas reservas seguidas. Chámanos por teléfono.'],
    'La reserva no existe' => ['en' => 'The booking doesn’t exist', 'pt' => 'A reserva não existe', 'gl' => 'A reserva non existe'],
    'Demasiados intentos. Espera 15 minutos.' => ['en' => 'Too many attempts. Wait 15 minutes.', 'pt' => 'Demasiadas tentativas. Aguarde 15 minutos.', 'gl' => 'Demasiados intentos. Agarda 15 minutos.'],
    'No se pudo crear la cuenta' => ['en' => 'The account couldn’t be created', 'pt' => 'Não foi possível criar a conta', 'gl' => 'Non se puido crear a conta'],
