    'Tienes que aceptar las condiciones de uso y la política de privacidad' => ['en' => 'You need to accept the terms of use and the privacy policy', 'pt' => 'Tem de aceitar as condições de utilização e a política de privacidade', 'gl' => 'Tes que aceptar as condicións de uso e a política de privacidade'],
    'Ya hay una cuenta con ese email. Entra con tu contraseña.' => ['en' => 'There’s already an account with that email. Sign in with your password.', 'pt' => 'Já existe uma conta com esse email. Entre com a sua palavra-passe.', 'gl' => 'Xa hai unha conta con ese correo. Entra co teu contrasinal.'],
    'Email o contraseña incorrectos' => ['en' => 'Incorrect email or password', 'pt' => 'Email ou palavra-passe incorretos', 'gl' => 'Correo ou contrasinal incorrectos'],
    'Tu cuenta aún no está activada. Abre el enlace que te enviamos por email (mira también en spam).' => ['en' => 'Your account isn’t activated yet. Open the link we sent you by email (check spam too).', 'pt' => 'A sua conta ainda não está ativada. Abra a ligação que lhe enviámos por email (veja também no spam).', 'gl' => 'A túa conta aínda non está activada. Abre a ligazón que che enviamos por correo (mira tamén no spam).'],
    'Ese email ya lo usa otra cuenta' => ['en' => 'That email is already used by another account', 'pt' => 'Esse email já é usado por outra conta', 'gl' => 'Ese correo xa o usa outra conta'],
